import { z } from 'zod';
import { positionSchema } from './position';

/** The workspace every account starts with. */
export const DEFAULT_WORKSPACE_NAME = 'Personal';

export const workspaceRoleSchema = z.enum(['owner', 'member']);
export type WorkspaceRole = z.infer<typeof workspaceRoleSchema>;

/** A group of projects, such as personal and work, or one per client. */
export const workspaceSchema = z.object({
  /** UUIDv7 generated by the client, so a workspace can be made offline. */
  id: z.uuid(),
  name: z.string().trim().min(1).max(60),
  position: positionSchema,
});
export type Workspace = z.infer<typeof workspaceSchema>;

export const createWorkspaceSchema = workspaceSchema;
export type CreateWorkspace = z.infer<typeof createWorkspaceSchema>;

export const updateWorkspaceSchema = workspaceSchema
  .pick({ name: true, position: true })
  .partial()
  .strict();
export type UpdateWorkspace = z.infer<typeof updateWorkspaceSchema>;

/**
 * Who may see a workspace. The first version is used by one person, but rows hang off
 * membership rather than a user so sharing needs no data migration (docs/spec.md).
 */
export const workspaceMemberSchema = z.object({
  workspaceId: z.uuid(),
  userId: z.string().min(1),
  role: workspaceRoleSchema,
});
export type WorkspaceMember = z.infer<typeof workspaceMemberSchema>;
